namespace InventoryApp.Services;

public record EquipmentItem(
    int Id,
    string Name,
    string Location,
    DateTime LastInspected);

public class EquipmentService
{
    public async Task<List<EquipmentItem>> GetEquipmentAsync()
    {
        // Simulate a slow data source
        await Task.Delay(500);

        return new List<EquipmentItem>
        {
            new(1, "Hydraulic Press",     "Building A – Bay 3",  new DateTime(2026, 6, 10)),
            new(2, "CNC Lathe",           "Building B – Bay 1",  new DateTime(2026, 5, 22)),
            new(3, "Arc Welder",          "Building A – Bay 7",  new DateTime(2026, 6, 1)),
            new(4, "Forklift #12",        "Warehouse C",         new DateTime(2026, 4, 15)),
            new(5, "Overhead Crane",      "Building D – Bay 2",  new DateTime(2026, 3, 30)),
            new(6, "Band Saw",            "Building A – Bay 5",  new DateTime(2026, 6, 18)),
            new(7, "Air Compressor",      "Utility Room 1",      new DateTime(2026, 5, 5)),
            new(8, "Drill Press",         "Building B – Bay 4",  new DateTime(2026, 6, 25)),
        };
    }
}

@page "/inventory"
@rendermode InteractiveServer
@inject InventoryApp.Services.EquipmentService EquipmentService
@inject PersistentComponentState ApplicationState
@implements IDisposable

<PageTitle>Inventory</PageTitle>

<h1>Equipment Inventory</h1>

@if (equipment is null)
{
    <p><em>Loading inventory...</em></p>
}
else
{
    <table class="table">
        <thead>
            <tr>
                <th>Id</th>
                <th>Name</th>
                <th>Location</th>
                <th>Last Inspected</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var item in equipment)
            {
                <tr>
                    <td>@item.Id</td>
                    <td>@item.Name</td>
                    <td>@item.Location</td>
                    <td>@item.LastInspected.ToShortDateString()</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private List<EquipmentItem>? equipment;
    private PersistingComponentStateSubscription _subscription;

    protected override async Task OnInitializedAsync()
    {
        _subscription = ApplicationState.RegisterOnPersisting(PersistData);

        if (ApplicationState.TryTakeFromJson<List<EquipmentItem>>(
                nameof(equipment), out var restored))
        {
            // Interactive render: reuse data persisted during prerender
            equipment = restored;
        }
        else
        {
            // Prerender: fetch from the service (only call)
            equipment = await EquipmentService.GetEquipmentAsync();
        }
    }

    private Task PersistData()
    {
        ApplicationState.PersistAsJson(nameof(equipment), equipment);
        return Task.CompletedTask;
    }

    public void Dispose() => _subscription.Dispose();
}

